SELECT s.store_name AS storeName, i.ingredient_name AS ingredientName, i.storage_type AS storageType, od.current_quantity AS currentQuantity, i.order_unit AS orderUnit, od.store_at AS storeAt, iu.management_start_at AS managementStartAt, u.user_name AS userName FROM order_details od JOIN orders o ON od.order_id = o.order_id JOIN stores s ON o.store_id = s.store_id JOIN ingredients i ON od.ingredient_id = i.ingredient_id LEFT JOIN inventory_usages iu ON iu.order_detail_id = od.order_detail_id LEFT JOIN users u ON o.user_id = u.user_id WHERE od.current_quantity > 0
AND i.ingredient_id = #{ingredientId}
AND s.store_id = #{storeId}
AND od.store_at >= #{storeStartDate}
AND od.store_at < DATE_ADD(#{storeEndDate}, INTERVAL 1 DAY)
AND iu.management_start_at >= #{manageStartDate}
AND iu.management_start_at < DATE_ADD(#{manageEndDate}, INTERVAL 1 DAY)
ORDER BY s.store_name, i.ingredient_name, od.store_at, iu.management_start_at

SELECT s.store_name AS storeName, i.sub_category_name AS subCategoryName, i.ingredient_name AS ingredientName, i.storage_type AS storageType, od.current_quantity AS currentQuantity, i.order_unit AS orderUnit, u.user_name AS userName FROM order_details od JOIN orders o ON od.order_id = o.order_id JOIN stores s ON o.store_id = s.store_id JOIN users u ON s.user_id = u.user_id JOIN ingredients i ON od.ingredient_id = i.ingredient_id WHERE od.current_quantity > 0 AND o.store_id = #{storeId}
AND i.sub_category_name = #{subCategoryName}
AND i.ingredient_id = #{ingredientId}
ORDER BY i.sub_category_name, i.ingredient_name, od.store_at
